style.css:
@-moz-document domain("open.spotify.com") {
/* fundo mais claro pra combinar com texto preto */
body {
    background-color: #fff5f7 !important;
}

/* textos pretos */
span, p, h1, h2, h3, a {
    color: #000000 !important;
}

/* sidebar */
nav {
    background-color: #ffeef2 !important;
}

/* área principal */
main {
    background-color: #fff5f7 !important;
}

/* botões */
button {
    border-radius: 12px !important;
}

button:hover {
    box-shadow: 0 0 6px rgba(255, 105, 180, 0.4) !important;
}

/* cards */
div {
    background-color: rgba(255, 255, 255, 0.7);
    border-radius: 12px;
}

/* barra de progresso */
progress::-webkit-progress-value {
    background-color: #ff8fab !important;
}
}
